import{_ as o,o as d,c as t,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const u=JSON.parse('{"title":"Extending the Engine","description":"","frontmatter":{},"headers":[],"relativePath":"dynamic-record-view/extending.md","filePath":"dynamic-record-view/extending.md"}'),n={name:"dynamic-record-view/extending.md"};function a(c,e,r,l,s,p){return d(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="extending-the-engine" tabindex="-1">Extending the Engine <a class="header-anchor" href="#extending-the-engine" aria-label="Permalink to &quot;Extending the Engine&quot;">​</a></h1><p>Status: <strong>Implemented</strong> (these are the real, exercised extension points).</p><h2 id="add-a-new-field-type" tabindex="-1">Add a new field type <a class="header-anchor" href="#add-a-new-field-type" aria-label="Permalink to &quot;Add a new field type&quot;">​</a></h2><p>Extend <code>App\\Support\\DynamicRecordView\\Core\\Fields\\Field</code> (see <code>TextViewField</code>, <code>MoneyViewField</code>, <code>RelationViewField</code> for the shape). Override <code>resolveValue()</code> only if the field needs non-default value resolution (dotted relation paths, computed values); override <code>formattedValue()</code> for type-specific default display formatting that <code>formatUsing()</code> should still be able to override. Then teach <code>resources/views/components/dynamic-record-view/fields-content.blade.php</code> how to render it if it needs special markup beyond the generic value/badge/link branches already there (e.g. <code>LinkViewField</code>&#39;s <code>method_exists($field, &#39;getUrl&#39;)</code> branch).</p><p>If the new field type resolves a relation path (like <code>RelationViewField</code>), also update <code>DynamicRecordView::requiredEagerLoads()</code> if it should contribute to eager-loading — currently that method only recognizes <code>RelationViewField</code> specifically.</p><h2 id="add-a-new-content-block-type" tabindex="-1">Add a new content block type <a class="header-anchor" href="#add-a-new-content-block-type" aria-label="Permalink to &quot;Add a new content block type&quot;">​</a></h2><p>Extend <code>App\\Support\\DynamicRecordView\\Core\\Content\\Content</code> (see <code>FieldsContent</code>, <code>TableContent</code>, <code>EmptyStateContent</code>, <code>SubApplicationContent</code>). Register its rendering in <code>resources/views/components/dynamic-record-view/content.blade.php</code>&#39;s <code>@if</code>/<code>@elseif</code> chain, keyed on <code>instanceof</code>.</p><h2 id="add-a-new-record-view" tabindex="-1">Add a new record view <a class="header-anchor" href="#add-a-new-record-view" aria-label="Permalink to &quot;Add a new record view&quot;">​</a></h2><ol><li>Create a Core definition extending <code>DynamicRecordView</code> in the owning module&#39;s <code>System/</code> directory (see <code>Modules\\General\\System\\SubModuleRecordView</code>, <code>Modules\\General\\System\\World\\CountryRecordView</code>) — implement <code>model()</code>, <code>query()</code>, <code>title()</code>, optionally <code>subtitle()</code>, <code>tabs()</code>, <code>subApplications()</code>.</li><li>Register it: <code>RecordViewRegistry::register($key, static::class)</code> — see <code>Modules\\General\\Providers\\GeneralServiceProvider</code> for where the existing two are registered.</li><li>Create the module&#39;s own Livewire full-page wrapper (see <code>Modules\\General\\Livewire\\SubModuleRecordView</code>) and route it in the module&#39;s <code>Routes/web.php</code>.</li><li>If it embeds a relation, create/reuse a <code>Table</code> subclass for it (see <a href="./embedded-tables">embedded-tables.md</a>) and, if Link/Unlink is wanted, a <code>RelationshipActions</code>/<code>RelationPicker</code> pair (see <a href="./relationship-actions">relationship-actions.md</a>).</li></ol><h2 id="add-link-unlink-to-a-new-relation" tabindex="-1">Add Link/Unlink to a new relation <a class="header-anchor" href="#add-link-unlink-to-a-new-relation" aria-label="Permalink to &quot;Add Link/Unlink to a new relation&quot;">​</a></h2><p>Call <code>-&gt;relationshipActions(RelationshipActions::make()-&gt;linkExisting(...))</code> (and <code>-&gt;unlinkable()</code> if the FK is nullable) on the <code>SubApplication</code> or <code>TableContent</code>. <code>RelationshipActions::assertSupportedFor()</code> runs at definition time and will throw immediately if the relation type/shape isn&#39;t supported (<code>HasMany</code>, <code>BelongsToMany</code>, <code>MorphMany</code> only) or if Unlink is requested against a non-nullable FK — see <a href="./relationship-actions">relationship-actions.md</a> and <a href="./troubleshooting">troubleshooting.md</a>.</p>',11)])])}const m=o(n,[["render",a]]);export{u as __pageData,m as default};
